export type Product = {
  id: string; slug: string; name: string; category: string; form: string; size: string;
  price: number; mrp: number; hairTypes: string[]; concerns: string[]; stock: number; badge: string;
  colors: Record<string, string>; short: string; ingredients: string[]; howto: string;
  rating: number; reviews: number; image: string; desc: string; archived?: boolean;
};
export type User = { email: string; name: string; phone?: string; address?: string };
export type CartLine = { id: string; qty: number; product: Product };
export type CartDetail = { lines: CartLine[]; count: number; subtotal: number; discount: number; shipping: number; total: number };
export type OrderStatus = 'placed' | 'packed' | 'shipped' | 'out_for_delivery' | 'delivered' | 'cancelled';
export type Order = {
  id: string; email: string; name: string; phone?: string; address?: string; city?: string; pin?: string;
  items: { id: string; name: string; price: number; qty: number }[];
  subtotal: number; discount?: number; shipping: number; total: number; payment: string; status: OrderStatus;
  history: { status: OrderStatus; at: string }[]; createdAt: string; paymentRef?: string; demo?: boolean;
};
export type ProductQuery = { search?: string; category?: string; hairType?: string; concern?: string; sort?: string; maxPrice?: number; inStock?: boolean };
type Store = { getItem(k: string): any; setItem(k: string, v: string): any; removeItem?(k: string): any };
export function useStorage(s: Store): void;
export function subscribe(fn: (key: string) => void): () => void;
export function listProducts(q?: ProductQuery): Promise<Product[]>;
export function getProduct(idOrSlug: string): Promise<Product | null>;
export function saveProduct(p: Partial<Product>): Promise<Product>;
export function deleteProduct(id: string): Promise<any>;
export function adjustStock(id: string, delta: number): Promise<Product | undefined>;
export const FILTERS: { categories: string[]; hairTypes: string[]; concerns: string[] };
export function currentUser(): Promise<User | null>;
export function login(email: string, password: string): Promise<User>;
export function signup(a: { name: string; email: string; password: string }): Promise<User>;
export function updateProfile(patch: Partial<User>): Promise<User | null>;
export function logout(): Promise<void>;
export function getCart(): Promise<{ id: string; qty: number }[]>;
export function addToCart(id: string, qty?: number): Promise<any>;
export function setQty(id: string, qty: number): Promise<any>;
export function clearCart(): Promise<any>;
export function cartDetail(coupon?: string): Promise<CartDetail>;
export function getWishlist(): Promise<string[]>;
export function toggleWish(id: string): Promise<boolean>;
export function placeOrder(a: { name: string; email: string; phone: string; address: string; city: string; pin: string; payment: string; coupon?: string }): Promise<Order>;
export function listOrders(email?: string): Promise<Order[]>;
export function getOrder(id: string): Promise<Order | null>;
export function setOrderStatus(id: string, status: OrderStatus): Promise<Order | null>;
export function advanceOrder(id: string): Promise<Order | null>;
export function resetDemo(): Promise<any>;
export const STATUSES: OrderStatus[];
export const STATUS_LABEL: Record<string, string>;
export function money(n: number): string;
export function eta(o: Order): string;
